// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.34;

import { IERC20 } from "@oz/interfaces/IERC20.sol";
import { Authority } from "@solmate/auth/Auth.sol";

import { IFeeCalculator } from "src/core/interfaces/IFeeCalculator.sol";
import { ISubmitHooks } from "src/core/interfaces/ISubmitHooks.sol";
import { IWhitelist } from "src/core/interfaces/IWhitelist.sol";
import { IOracle } from "src/dependencies/oracles/IOracle.sol";

/// @notice Type of request: deposit/redeem and auto/fixed price
/// @dev
/// - The order is chosen so each bit encodes a property:
///   - Bit 0: 0 = deposit, 1 = redeem
///   - Bit 1: 0 = auto price, 1 = fixed price
enum RequestType {
    DEPOSIT_AUTO_PRICE, // 00: deposit, auto price
    REDEEM_AUTO_PRICE, // 01: redeem, auto price
    DEPOSIT_FIXED_PRICE, // 10: deposit, fixed price
    REDEEM_FIXED_PRICE // 11: redeem, fixed price
}

/// @notice Type of return value: no return, static return, dynamic return
/// @dev
/// - 00: no return
/// - 01: static return - hardcoded return data
/// - 10: dynamic return - return data is extracted from the results array
enum ReturnValueType {
    NO_RETURN,
    STATIC_RETURN,
    DYNAMIC_RETURN
}

/// @notice Type of hook call: before, after, or none
enum HookCallType {
    NONE,
    BEFORE,
    AFTER
}

/// @notice Operation struct for vault operations
/// @dev This struct is not used directly in core logic, but included for reference and clarity
///      It illustrates the full structure of an operation without storage packing
struct Operation {
    /// @notice Target contract address to call
    address target;
    /// @notice Calldata for the target contract
    bytes data;
    /// @notice Array of clipboard operations for copying return data
    Clipboard[] clipboards;
    /// @notice Whether to perform a static call
    bool isStaticCall;
    /// @notice Callback data for post-operation processing
    CallbackData callbackData;
    /// @notice Address of the hooks contract
    address hooks;
    /// @notice Array of offsets for extracting calldata
    uint16[] configurableHooksOffsets;
    /// @notice Merkle proof for operation verification
    bytes32[] proof;
    /// @notice ETH value to send with the call
    uint256 value;
}

/// @notice Operation execution context data
/// @dev Used to avoid stack too deep in BaseVault._executeSubmit function
struct OperationContext {
    /// @notice Address of the target contract to call
    address target;
    /// @notice Function selector extracted from calldata
    bytes4 selector;
    /// @notice Callback data packed
    uint208 callbackData;
    /// @notice ETH value to send with the call
    uint256 value;
    /// @notice Address of the operation-specific hooks contract
    address operationHooks;
    /// @notice Offset of the calldata extraction offsets packed in uint256
    uint256 configurableOperationHooks;
}

/// @notice Struct for payable operations
struct OperationPayable {
    /// @notice Target contract address
    address target;
    /// @notice Calldata for the target contract
    bytes data;
    /// @notice ETH value to send with the call
    uint256 value;
}

/// @notice Struct for token approvals
struct Approval {
    /// @notice Token address to approve
    address token;
    /// @notice Address to approve spending for
    address spender;
}

/// @notice Struct for token amounts
struct TokenAmount {
    /// @notice ERC20 token address
    IERC20 token;
    /// @notice Amount of tokens
    uint256 amount;
}

/// @notice Struct for clipboard operations
struct Clipboard {
    /// @notice Index of the result to copy from
    uint8 resultIndex;
    /// @notice Which word to copy from the result
    uint8 copyWord;
    /// @notice Offset to paste the copied data
    uint16 pasteOffset;
}

/// @notice Struct for callback data
struct CallbackData {
    /// @notice Address allowed to execute the callback
    address caller;
    /// @notice Function selector for the callback
    bytes4 selector;
    /// @notice Offset in calldata for the callback
    uint16 calldataOffset;
}

/// @notice Vault parameters for vault deployment
struct BaseVaultParameters {
    /// @notice Initial owner address
    address owner;
    /// @notice Initial authority address
    Authority authority;
    /// @notice Submit hooks address
    ISubmitHooks submitHooks;
    /// @notice Whitelist contract address
    IWhitelist whitelist;
}

/// @notice Parameters for fee vault deployment
struct FeeVaultParameters {
    /// @notice The fee calculator address
    IFeeCalculator feeCalculator;
    /// @notice The fee token address
    IERC20 feeToken;
    /// @notice The fee recipient address
    address feeRecipient;
}

/// @notice Parameters for ERC20 deployment
struct ERC20Parameters {
    /// @notice ERC20 token name
    string name;
    /// @notice ERC20 token symbol
    string symbol;
}

/// @notice Fee structure for TVL and performance fees
/// @dev All fees are in basis points (1/10000)
struct Fee {
    /// @notice TVL fee in basis points
    uint16 tvl;
    /// @notice Performance fee in basis points
    uint16 performance;
}

/// @notice Tracks fee configuration and accrued fees for a vault
struct VaultAccruals {
    /// @notice Current fee rates for the vault
    Fee fees;
    /// @notice Accrued fees for the vault fee recipient
    uint112 accruedFees;
    /// @notice Total protocol fees accrued but not claimed
    uint112 accruedProtocolFees;
}

/// @notice Complete state of a vault's fee configuration and accruals
struct VaultSnapshot {
    /// @notice Timestamp of last fee accrual
    uint32 lastFeeAccrual;
    /// @notice Timestamp when snapshot was taken
    uint32 timestamp;
    /// @notice Timestamp when snapshot is finalized after dispute period
    uint32 finalizedAt;
    /// @notice Average value of vault assets during snapshot period
    uint160 averageValue;
    /// @notice Highest profit achieved during snapshot period
    uint128 highestProfit;
    /// @notice Highest profit achieved in previous periods
    uint128 lastHighestProfit;
}

/// @notice Struct for target and calldata
struct TargetCalldata {
    /// @notice Target contract address
    address target;
    /// @notice Calldata for the target contract
    bytes data;
}

/// @notice Vault price information and configuration
struct VaultPriceStateV2 {
    /// @notice Whether vault price updates are paused
    bool paused;
    /// @notice Whether policy-violating anchor updates pause (`true`) or revert (`false`)
    bool pauseOnBadAnchorUpdate;
    /// @notice Maximum age of price data in seconds before it is considered stale
    uint16 maxPriceAge;
    /// @notice Minimum time between anchor updates in minutes
    uint16 minUpdateIntervalMinutes;
    /// @notice Maximum allowed price increase ratio in basis points
    uint16 maxPriceToleranceRatio;
    /// @notice Minimum allowed price decrease ratio in basis points
    uint16 minPriceToleranceRatio;
    /// @notice Maximum allowed delay in price updates in days
    uint8 maxUpdateDelayDays;
    /// @notice Seconds between last fee accrual and last anchor update
    uint32 accrualLag;
    /// @notice Timestamp of last anchor update
    uint32 anchorTimestamp;
    /// @notice Timestamp of last drift update
    uint32 driftTimestamp;
    /// @notice Current anchor price
    uint128 anchorPrice;
    /// @notice Current drift price
    uint128 driftPrice;
    /// @notice Highest historical price
    uint128 highestPrice;
    /// @notice Total supply at last price update
    uint128 lastTotalSupply;
}

/// @notice Full token configuration stored on-chain
struct TokenDetailsV2 {
    /// @notice Whether async deposits are enabled
    bool asyncDepositEnabled;
    /// @notice Whether async redemptions are enabled
    bool asyncRedeemEnabled;
    /// @notice Whether sync deposits are enabled
    bool syncDepositEnabled;
    /// @notice Whether sync redeems are enabled
    bool syncRedeemEnabled;
    /// @notice Premium multiplier for async deposits in basis points (9999 = 0.1% premium)
    uint16 asyncDepositMultiplier;
    /// @notice Premium multiplier for async redeems in basis points (9999 = 0.1% premium)
    uint16 asyncRedeemMultiplier;
    /// @notice Premium multiplier for sync deposits in basis points (9999 = 0.1% premium)
    uint16 syncDepositMultiplier;
    /// @notice Premium multiplier for sync redeems in basis points (9999 = 0.1% premium)
    /// @dev Used as per-token flat premium component for sync redeem
    uint16 syncRedeemMultiplier;
    /// @notice SSTORE2 pointer for push-funds submit data
    /// @dev address(0) means push-funds is disabled for that token
    address pushFundsSubmitDataPointer;
    /// @notice SSTORE2 pointer for pull-funds submit data
    /// @dev address(0) means pull-funds is disabled for that token
    address pullFundsSubmitDataPointer;
}

/// @notice Request parameters for deposits and redemptions
/// @dev
/// - For deposits:
///   - units: minimum units the user wants to receive (minUnitsOut)
///   - tokens: amount of tokens the user is providing (tokensIn)
/// - For redemptions:
///   - units: amount of units the user is redeeming (unitsIn)
///   - tokens: minimum tokens the user wants to receive (minTokensOut)
struct RequestV2 {
    /// @notice Request type(deposit/redeem + auto/fixed price)
    RequestType requestType;
    /// @notice User address making the request
    address user;
    /// @notice Address that gets units/tokens when the order is solved
    address receiver;
    /// @notice Amount of vault units
    uint256 units;
    /// @notice Amount of underlying tokens
    uint256 tokens;
    /// @notice Tip paid to solver, always in tokens
    uint256 solverTip;
    /// @notice Timestamp after which request expires
    uint256 deadline;
    /// @notice Maximum age of price data allowed
    uint256 maxPriceAge;
}

/// @notice Oracle data for a base/quote pair, including current, pending, and status flags
struct OracleData {
    /// @notice True if an oracle update is scheduled
    bool isScheduledForUpdate;
    /// @notice True if the current oracle is disabled
    bool isDisabled;
    /// @notice The currently active oracle
    IOracle oracle;
    /// @notice The pending oracle to be activated after delay
    IOracle pendingOracle;
    /// @notice Timestamp at which the pending oracle can be committed
    uint32 commitTimestamp;
}

src/core/interfaces/IBaseVault.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.34;

import { HookCallType } from "src/core/Types.sol";
import { ISubmitHooks } from "src/core/interfaces/ISubmitHooks.sol";

/// @title IBaseVault
/// @notice Interface for the BaseVault
interface IBaseVault {
    ////////////////////////////////////////////////////////////
    //                         Events                         //
    ////////////////////////////////////////////////////////////

    /// @notice Emitted when submit hooks are updated
    /// @param submitHooksAddress The new submit hooks contract address
    event SubmitHooksSet(address indexed submitHooksAddress);

    /// @notice Emitted when a guardian's merkle root is set
    /// @param guardian The guardian's address
    /// @param root The new merkle root for the guardian
    event GuardianRootSet(address indexed guardian, bytes32 indexed root);

    ////////////////////////////////////////////////////////////
    //                         Errors                         //
    ////////////////////////////////////////////////////////////

    error Aera__ZeroAddressGuardian();
    error Aera__ZeroAddressOwner();
    error Aera__CallerIsNotGuardian();
    error Aera__CallerIsNotAuthOrGuardian();
    error Aera__SubmissionFailed(uint256 index, bytes result);
    error Aera__AllowanceIsNotZero(address token, address spender);
    error Aera__ZeroAddressMerkleRoot();
    error Aera__BeforeSubmitHooksFailed(bytes result);
    error Aera__AfterSubmitHooksFailed(bytes result);
    error Aera__BeforeOperationHooksFailed(uint256 index, bytes result);
    error Aera__AfterOperationHooksFailed(uint256 index, bytes result);
    error Aera__BeforeOperationHooksWithConfigurableHooks();
    error Aera__ProofVerificationFailed();
    error Aera__InvalidBeforeOperationHooksReturnDataLength();
    error Aera__GuardianNotWhitelisted();
    error Aera__ExpectedCallbackNotReceived();
    error Aera__NoResults();

    ////////////////////////////////////////////////////////////
    //                       Functions                        //
    ////////////////////////////////////////////////////////////

    /// @notice Submit a series of operations to the vault
    /// @param data Encoded array of operations to submit
    /// ┌─────────────────────────────┬─────────────────────────┬───────────────────────────────────────────────┐
    /// │ FIELDS                      │ SIZE                    │ DESCRIPTION                                   │
    /// ├─────────────────────────────┴─────────────────────────┴───────────────────────────────────────────────┤
    /// │ operationsLength              1 byte                    Number of operations in the array             │
    /// │                                                                                                       │
    /// │ [for each operation]:                                                                                 │
    /// │                                                                                                       │
    /// │   SIGNATURE                                                                                           │
    /// │   target                      20 bytes                  Target contract address                       │
    /// │   calldataLength              2 bytes                   Length of calldata                            │
    /// │   calldata                    <calldataLength> bytes    Calldata (before pipelining)                  │
    /// │                                                                                                       │
    /// │   CLIPBOARD                                                                                           │
    /// │   clipboardsLength            1 byte                    Number of clipboards                          │
    /// │   [for each clipboard entry]:                                                                         │
    /// │       resultIndex             1 byte                    Which operation to take from                  │
    /// │       copyWord                1 byte                    Which word to copy                            │
    /// │       pasteOffset             2 bytes                   What offset to paste it at                    │
    /// │                                                                                                       │
    /// │   CALL TYPE                                                                                           │
    /// │   isStaticCall                1 byte                    1 if static, 0 if a regular call              │
    /// │   [if isStaticCall == 0]:                                                                             │
    /// │                                                                                                       │
    /// │     CALLBACK HANDLING                                                                                 │
    /// │     hasCallback               1 byte                    Whether to allow callbacks during operation   │
    /// │     [if hasCallback == 1]:                                                                            │
    /// │       callbackData =          26 bytes                  Expected callback info                        │
    /// │       ┌────────────────────┬──────────────────────────┬───────────────────┐                           │
    /// │       │ selector (4 bytes) │ calldataOffset (2 bytes) │ caller (20 bytes) │                           │
    /// │       └────────────────────┴──────────────────────────┴───────────────────┘                           │
    /// │                                                                                                       │
    /// │     HOOKS                                                                                             │
    /// │     hookConfig =              1 byte                    Hook configuration                            │
    /// │     ┌─────────────────┬────────────────────────────────────────┐                                      │
    /// │     │ hasHook (1 bit) │ configurableHookOffsetsLength (7 bits) │                                      │
    /// │     └─────────────────┴────────────────────────────────────────┘                                      │
    /// │     if configurableHookOffsetsLength > 0:                                                             │
    /// │         configurableHookOffsets 32 bytes                Packed configurable hook offsets              │
    /// │     if hasHook == 1:                                                                                  │
    /// │         hook                 20 bytes                   Hook contract address                         │
    /// │                                                                                                       │
    /// │     MERKLE PROOF                                                                                      │
    /// │     proofLength              1 byte                     Merkle proof length                           │
    /// │     proof                    <proofLength> * 32 bytes   Merkle proof data                             │
    /// │                                                                                                       │
    /// │     PAYABILITY                                                                                        │
    /// │     hasValue                 1 byte                     Whether to send native token with the call    │
    /// │     [if hasValue == 1]:                                                                               │
    /// │       value                  32 bytes                   Amount of native token to send                │
    /// └───────────────────────────────────────────────────────────────────────────────────────────────────────┘
    function submit(bytes calldata data) external;

    /// @notice Set the merkle root for a guardian
    /// Used to add guardians and update their permissions
    /// @param guardian Address of the guardian
    /// @param root Merkle root
    function setGuardianRoot(address guardian, bytes32 root) external;

    /// @notice Removes a guardian from the vault
    /// @param guardian Address of the guardian
    function removeGuardian(address guardian) external;

    /// @notice Set the submit hooks address
    /// @param newSubmitHooks Address of the new submit hooks contract
    function setSubmitHooks(ISubmitHooks newSubmitHooks) external;

    /// @notice Pause the vault, halting the ability for guardians to submit
    function pause() external;

    /// @notice Unpause the vault, allowing guardians to submit operations
    function unpause() external;

    /// @notice Check if the guardian is whitelisted and set the root to zero if not
    /// Used to disable guardians who were removed from the whitelist
    /// after being selected as guardians
    /// @param guardian The guardian address
    /// @return isRemoved Whether the guardian was removed from the whitelist
    function checkGuardianWhitelist(address guardian) external returns (bool isRemoved);

    /// @notice Get all active guardians
    /// @return Array of active guardian addresses
    function getActiveGuardians() external view returns (address[] memory);

    /// @notice Get the guardian root for a guardian
    /// @param guardian The guardian address
    /// @return The guardian root
    function getGuardianRoot(address guardian) external view returns (bytes32);

    /// @notice Get the current hook call type
    /// @return The current hook call type
    function getCurrentHookCallType() external view returns (HookCallType);
}

src/core/interfaces/IMultiDepositorVault.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.34;

import { IERC20 } from "@oz/interfaces/IERC20.sol";
import { IBeforeTransferHook } from "src/core/interfaces/IBeforeTransferHook.sol";

/// @title IMultiDepositorVault
/// @notice Interface for vaults that can accept deposits from multiple addresses
interface IMultiDepositorVault {
    ////////////////////////////////////////////////////////////
    //                         Events                         //
    ////////////////////////////////////////////////////////////

    /// @notice Emitted when the before transfer hook is updated
    /// @param beforeTransferHook The new before transfer hook address
    event BeforeTransferHookSet(address indexed beforeTransferHook);
    /// @notice Emitted when the provisioner is updated
    /// @param provisioner The new provisioner address
    event ProvisionerSet(address indexed provisioner);
    /// @notice Emitted when tokens are deposited into the vault
    /// @param sender The address initiating the deposit
    /// @param recipient The address receiving the vault units
    /// @param token The token being deposited
    /// @param tokenAmount The amount of tokens deposited
    /// @param unitsAmount The amount of vault units minted
    event Enter(
        address indexed sender,
        address indexed recipient,
        IERC20 indexed token,
        uint256 tokenAmount,
        uint256 unitsAmount
    );
    /// @notice Emitted when tokens are withdrawn from the vault
    /// @param sender The address initiating the withdrawal
    /// @param recipient The address receiving the tokens
    /// @param token The token being withdrawn
    /// @param tokenAmount The amount of tokens withdrawn
    /// @param unitsAmount The amount of vault units burned
    event Exit(
        address indexed sender,
        address indexed recipient,
        IERC20 indexed token,
        uint256 tokenAmount,
        uint256 unitsAmount
    );

    ////////////////////////////////////////////////////////////
    //                         Errors                         //
    ////////////////////////////////////////////////////////////

    error Aera__UnitsLocked();
    error Aera__ZeroAddressProvisioner();
    error Aera__CallerIsNotProvisioner();

    ////////////////////////////////////////////////////////////
    //                       Functions                        //
    ////////////////////////////////////////////////////////////

    /// @notice Set the before transfer hooks
    /// @param hooks The before transfer hooks address
    function setBeforeTransferHook(IBeforeTransferHook hooks) external;

    /// @notice Deposit tokens into the vault and mint units
    /// @param sender The sender of the tokens
    /// @param token The token to deposit
    /// @param tokenAmount The amount of token to deposit
    /// @param unitsAmount The amount of units to mint
    /// @param recipient The recipient of the units
    function enter(address sender, IERC20 token, uint256 tokenAmount, uint256 unitsAmount, address recipient)
        external;

    /// @notice Withdraw tokens from the vault and burn units
    /// @param sender The sender of the units
    /// @param token The token to withdraw
    /// @param tokenAmount The amount of token to withdraw
    /// @param unitsAmount The amount of units to burn
    /// @param recipient The recipient of the tokens
    function exit(address sender, IERC20 token, uint256 tokenAmount, uint256 unitsAmount, address recipient) external;
}

src/core/interfaces/IPriceAndFeeCalculat.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.34;

import { IERC20 } from "@oz/token/ERC20/IERC20.sol";
import { Math } from "@oz/utils/math/Math.sol";
import { VaultAccruals, VaultPriceStateV2 } from "src/core/Types.sol";
import { IVersioned } from "src/core/interfaces/IVersioned.sol";

/// @title IPriceAndFeeCalculator
/// @notice Interface for the unit price provider
interface IPriceAndFeeCalculatorV2 is IVersioned {
    ////////////////////////////////////////////////////////////
    //                         Events                         //
    ////////////////////////////////////////////////////////////

    /// @notice Emitted when thresholds are set for a vault
    /// @param vault The address of the vault
    /// @param minPriceToleranceRatio Minimum ratio (of a price decrease) in basis points
    /// @param maxPriceToleranceRatio Maximum ratio (of a price increase) in basis points
    /// @param minUpdateIntervalMinutes The minimum interval between updates in minutes
    /// @param maxPriceAge Max delay between when a vault was priced and when the price is acceptable
    /// @param maxUpdateDelayDays Max delay between two price updates in days
    event ThresholdsSet(
        address indexed vault,
        uint16 minPriceToleranceRatio,
        uint16 maxPriceToleranceRatio,
        uint16 minUpdateIntervalMinutes,
        uint16 maxPriceAge,
        uint8 maxUpdateDelayDays
    );

    /// @notice Emitted when we change whether out-of-range updates should pause or revert
    /// @param vault The address of the vault
    /// @param pauseOnBadAnchorUpdate True to pause on bad anchor update, false to revert
    event PauseOnBadAnchorUpdateChanged(address indexed vault, bool pauseOnBadAnchorUpdate);

    /// @notice Emitted when a vault's anchor price is updated
    /// @param vault The address of the vault
    /// @param price The new anchor price
    /// @param timestamp The timestamp of the new anchor price
    event AnchorPriceUpdated(address indexed vault, uint128 price, uint32 timestamp);

    /// @notice Emitted when a vault's drift price is updated
    /// @param vault The address of the vault
    /// @param price The new drift price
    /// @param timestamp The timestamp of the new drift price
    event DriftPriceUpdated(address indexed vault, uint128 price, uint32 timestamp);

    /// @notice Emitted when a vault's paused state is changed
    /// @param vault The address of the vault
    /// @param paused Whether the vault is paused
    event VaultPausedChanged(address indexed vault, bool paused);

    /// @notice Emitted when a vault's highest price is reset
    /// @param vault The address of the vault
    /// @param newHighestPrice The new highest price
    event HighestPriceReset(address indexed vault, uint128 newHighestPrice);

    ////////////////////////////////////////////////////////////
    //                         Errors                         //
    ////////////////////////////////////////////////////////////

    error Aera__StalePrice();
    error Aera__TimestampMustBeAfterLastUpdate();
    error Aera__TimestampCantBeInFuture();
    error Aera__ZeroAddressOracleRegistry();
    error Aera__InvalidMaxPriceToleranceRatio();
    error Aera__InvalidMinPriceToleranceRatio();
    error Aera__InvalidMaxPriceAge();
    error Aera__InvalidMaxUpdateDelayDays();
    error Aera__ThresholdNotSet();
    error Aera__VaultPaused();
    error Aera__VaultNotPaused();
    error Aera__UnitPriceMismatch();
    error Aera__TimestampMismatch();
    error Aera__VaultAlreadyInitialized();
    error Aera__VaultNotInitialized();
    error Aera__InvalidPrice();
    error Aera__CurrentPriceAboveHighestPrice();
    error Aera__DriftOutsideAnchorBand();
    error Aera__MaxUpdateDelayExceeded();
    error Aera__BadAnchorPriceUpdate();

    ////////////////////////////////////////////////////////////
    //                       Functions                        //
    ////////////////////////////////////////////////////////////

    /// @notice Set the initial anchor price state for the vault
    /// @param vault Address of the vault
    /// @param price New initial anchor price
    function setInitialPrice(address vault, uint128 price) external;

    /// @notice Set vault thresholds
    /// @param vault Address of the vault
    /// @param minPriceToleranceRatio Minimum ratio (of a price decrease) in basis points
    /// @param maxPriceToleranceRatio Maximum ratio (of a price increase) in basis points
    /// @param minUpdateIntervalMinutes The minimum interval between updates in minutes
    /// @param maxPriceAge Max delay between when a vault was priced and when the price is acceptable
    /// @param maxUpdateDelayDays Max delay between two price updates
    function setThresholds(
        address vault,
        uint16 minPriceToleranceRatio,
        uint16 maxPriceToleranceRatio,
        uint16 minUpdateIntervalMinutes,
        uint16 maxPriceAge,
        uint8 maxUpdateDelayDays
    ) external;

    /// @notice Set whether out-of-range updates should pause or revert
    /// @param vault Address of the vault
    /// @param pauseOnBadAnchorUpdate True to pause on bad anchor update, false to revert atomically
    /// @dev MUST be configurable by vault owner/authority
    function setPauseOnBadAnchorUpdate(address vault, bool pauseOnBadAnchorUpdate) external;

    /// @notice Set the anchor price for the vault in numeraire terms
    /// @param vault Address of the vault
    /// @param price New anchor price
    /// @param timestamp Timestamp when the anchor price was measured
    function setAnchorPrice(address vault, uint128 price, uint32 timestamp) external;

    /// @notice Set the drift price for the vault in numeraire terms
    /// @param vault Address of the vault
    /// @param price New drift price
    /// @param timestamp Timestamp when the drift price was measured
    /// @dev MUST revert when the vault is paused
    /// @dev MUST revert when drift update violates drift policy constraints
    function setDriftPrice(address vault, uint128 price, uint32 timestamp) external;

    /// @notice Pause the vault
    /// @param vault Address of the vault
    function pauseVault(address vault) external;

    /// @notice Unpause the vault
    /// @param vault Address of the vault
    /// @param price Expected anchor price at unpause time
    /// @param timestamp Expected anchor timestamp at unpause time
    /// @dev MUST revert if price or timestamp don't exactly match the current anchor tuple
    function unpauseVault(address vault, uint128 price, uint32 timestamp) external;

    /// @notice Resets the highest price for a vault to the current anchor price
    /// @param vault Address of the vault
    function resetHighestPrice(address vault) external;

    /// @notice Convert units to token amount
    /// @param vault Address of the vault
    /// @param token Address of the token
    /// @param unitsAmount Amount of units
    /// @return tokenAmount Amount of tokens
    function convertUnitsToToken(address vault, IERC20 token, uint256 unitsAmount)
        external
        view
        returns (uint256 tokenAmount);

    /// @notice Convert units to token amount if vault is not paused
    /// @param vault Address of the vault
    /// @param token Address of the token
    /// @param unitsAmount Amount of units
    /// @param rounding The rounding mode
    /// @return tokenAmount Amount of tokens
    /// @dev MUST revert if vault is paused
    function convertUnitsToTokenIfActive(address vault, IERC20 token, uint256 unitsAmount, Math.Rounding rounding)
        external
        view
        returns (uint256 tokenAmount);

    /// @notice Convert token amount to units
    /// @param vault Address of the vault
    /// @param token Address of the token
    /// @param tokenAmount Amount of tokens
    /// @return unitsAmount Amount of units
    function convertTokenToUnits(address vault, IERC20 token, uint256 tokenAmount)
        external
        view
        returns (uint256 unitsAmount);

    /// @notice Convert token amount to units if vault is not paused
    /// @param vault Address of the vault
    /// @param token Address of the token
    /// @param tokenAmount Amount of tokens
    /// @param rounding The rounding mode
    /// @return unitsAmount Amount of units
    /// @dev MUST revert if vault is paused
    function convertTokenToUnitsIfActive(address vault, IERC20 token, uint256 tokenAmount, Math.Rounding rounding)
        external
        view
        returns (uint256 unitsAmount);

    /// @notice Convert units to numeraire token amount
    /// @param vault Address of the vault
    /// @param unitsAmount Amount of units
    /// @return numeraireAmount Amount of numeraire
    function convertUnitsToNumeraire(address vault, uint256 unitsAmount) external view returns (uint256 numeraireAmount);

    /// @notice Convert units to numeraire token amount with rounding control
    /// @param vault Address of the vault
    /// @param unitsAmount Amount of units
    /// @param rounding The rounding mode
    /// @return numeraireAmount Amount of numeraire
    function convertUnitsToNumeraire(address vault, uint256 unitsAmount, Math.Rounding rounding)
        external
        view
        returns (uint256 numeraireAmount);

    /// @notice Convert numeraire amount to vault units
    /// @param vault Address of the vault
    /// @param numeraireAmount Amount of numeraire
    /// @param rounding The rounding mode
    /// @return unitsAmount Amount of units
    function convertNumeraireToUnits(address vault, uint256 numeraireAmount, Math.Rounding rounding)
        external
        view
        returns (uint256 unitsAmount);

    /// @notice Convert numeraire amount to token amount via oracle
    /// @param vault Address of the vault
    /// @param token Address of the token
    /// @param numeraireAmount Amount of numeraire
    /// @return tokenAmount Amount of tokens
    /// @dev Returns numeraireAmount unchanged when token is the numeraire
    function convertNumeraireToToken(address vault, IERC20 token, uint256 numeraireAmount)
        external
        view
        returns (uint256 tokenAmount);

    /// @notice Convert token amount to numeraire via oracle
    /// @param vault Address of the vault
    /// @param token Address of the token
    /// @param tokenAmount Amount of tokens
    /// @return numeraireAmount Amount of numeraire
    /// @dev Returns tokenAmount unchanged when token is the numeraire
    function convertTokenToNumeraire(address vault, IERC20 token, uint256 tokenAmount)
        external
        view
        returns (uint256 numeraireAmount);

    /// @notice Return the state of the vault
    /// @param vault Address of the vault
    /// @return vaultPriceState The price state of the vault
    /// @return vaultAccruals The accruals state of the vault
    function getVaultState(address vault) external view returns (VaultPriceStateV2 memory, VaultAccruals memory);

    /// @notice Returns the timestamp of the last submitted price for a vault
    /// @param vault Address of the vault
    /// @return timestamp The timestamp of the vault's last price update
    function getVaultPriceTimestamp(address vault) external view returns (uint256 timestamp);

    /// @notice Returns the timestamp of the last submitted anchor price for a vault
    /// @param vault Address of the vault
    /// @return timestamp The timestamp of the vault's current anchor price
    function getAnchorTimestamp(address vault) external view returns (uint32 timestamp);

    /// @notice Returns the vault value in numeraire at the last price update
    /// @param vault Address of the vault
    /// @return vaultValue The vault value in numeraire computed from lastTotalSupply and anchorPrice
    /// @dev MUST revert if the vault is paused
    function getVaultValueAtLastUpdate(address vault) external view returns (uint256 vaultValue);

    /// @notice Check if a vault is paused
    /// @param vault The address of the vault
    /// @return True if the vault is paused, false otherwise
    function isVaultPaused(address vault) external view returns (bool);
}

src/core/interfaces/IProvisionerV2.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.34;

import { IERC20 } from "@oz/token/ERC20/IERC20.sol";
import { RequestV2, TokenDetailsV2 } from "src/core/Types.sol";
import { IVersioned } from "src/core/interfaces/IVersioned.sol";

/// @title IProvisioner
/// @notice Interface for the contract that can mint and burn vault units in exchange for tokens
interface IProvisionerV2 is IVersioned {
    ////////////////////////////////////////////////////////////
    //                         Events                         //
    ////////////////////////////////////////////////////////////

    /// @notice Emitted when a user deposits tokens directly into the vault
    /// @param user The address of the depositor
    /// @param token The token being deposited
    /// @param tokensIn The amount of tokens deposited
    /// @param unitsOut The amount of units minted
    /// @param depositHash Unique identifier for this deposit
    event Deposited(
        address indexed user, IERC20 indexed token, uint256 tokensIn, uint256 unitsOut, bytes32 depositHash
    );

    /// @notice Emitted when a user deposits tokens directly into the vault
    /// @param user The address of the depositor
    /// @param receiver The address receiving the units
    /// @param token The token being deposited
    /// @param tokensIn The amount of tokens deposited
    /// @param unitsOut The amount of units minted
    /// @param depositHash Unique identifier for this deposit
    event Deposited(
        address indexed user,
        address indexed receiver,
        IERC20 indexed token,
        uint256 tokensIn,
        uint256 unitsOut,
        bytes32 depositHash
    );

    /// @notice Emitted when a deposit is refunded
    /// @param depositHash The hash of the deposit being refunded
    event DepositRefunded(bytes32 indexed depositHash);

    /// @notice Emitted when a direct (sync) deposit is refunded
    /// @param depositHash The hash of the deposit being refunded
    event DirectDepositRefunded(bytes32 indexed depositHash);

    /// @notice Emitted when a user creates a deposit request
    /// @param user The address requesting the deposit
    /// @param token The token being deposited
    /// @param tokensIn The amount of tokens to deposit
    /// @param minUnitsOut The minimum amount of units expected
    /// @param solverTip The tip offered to the solver in deposit token terms
    /// @param deadline Timestamp until which the request is valid
    /// @param maxPriceAge Maximum age of price data that solver can use
    /// @param isFixedPrice Whether the request is a fixed price request
    /// @param depositRequestHash The hash of the deposit request
    event DepositRequested(
        address indexed user,
        IERC20 indexed token,
        uint256 tokensIn,
        uint256 minUnitsOut,
        uint256 solverTip,
        uint256 deadline,
        uint256 maxPriceAge,
        bool isFixedPrice,
        bytes32 depositRequestHash
    );

    /// @notice Emitted when a user creates a redeem request
    /// @param user The address requesting the redemption
    /// @param token The token requested in return for units
    /// @param minTokensOut The minimum amount of tokens the user expects to receive
    /// @param unitsIn The amount of units being redeemed
    /// @param solverTip The tip offered to the solver in redeem token terms
    /// @param deadline The timestamp until which this request is valid
    /// @param maxPriceAge Maximum age of price data that solver can use
    /// @param isFixedPrice Whether the request is a fixed price request
    /// @param redeemRequestHash The hash of the redeem request
    event RedeemRequested(
        address indexed user,
        IERC20 indexed token,
        uint256 minTokensOut,
        uint256 unitsIn,
        uint256 solverTip,
        uint256 deadline,
        uint256 maxPriceAge,
        bool isFixedPrice,
        bytes32 redeemRequestHash
    );

    /// @notice Emitted when a deposit request is solved successfully
    /// @param depositHash The unique identifier of the deposit request that was solved
    event DepositSolved(bytes32 indexed depositHash);

    /// @notice Emitted when a redeem request is solved successfully
    /// @param redeemHash The unique identifier of the redeem request that was solved
    event RedeemSolved(bytes32 indexed redeemHash);

    /// @notice Emitted when an unrecognized async deposit hash is used
    /// @param depositHash The deposit hash that was not found in async records
    event InvalidRequestHash(bytes32 indexed depositHash);

    /// @notice Emitted when async deposits are disabled and a deposit request cannot be processed
    /// @param index The index of the deposit request that was rejected
    event AsyncDepositDisabled(uint256 indexed index);

    /// @notice Emitted when async redeems are disabled and a redeem request cannot be processed
    /// @param index The index of the redeem request that was rejected
    event AsyncRedeemDisabled(uint256 indexed index);

    /// @notice Emitted when the price age exceeds the maximum allowed for a request
    /// @param index The index of the request that was rejected
    event PriceAgeExceeded(uint256 indexed index);

    /// @notice Emitted when a deposit exceeds the vault's configured deposit cap
    /// @param index The index of the request that was rejected
    event DepositCapExceeded(uint256 indexed index);

    /// @notice Emitted when there are not enough tokens to cover the required solver tip
    /// @param index The index of the request that was rejected
    event InsufficientTokensForTip(uint256 indexed index);

    /// @notice Emitted when the output units are less than the amount requested
    /// @param index The index of the request that was rejected
    /// @param amount The actual amount
    /// @param bound The minimum amount
    event AmountBoundExceeded(uint256 indexed index, uint256 amount, uint256 bound);

    /// @notice Emitted when a redeem request is refunded due to expiration or cancellation
    /// @param redeemHash The unique identifier of the redeem request that was refunded
    event RedeemRefunded(bytes32 indexed redeemHash);

    /// @notice Emitted when cancellation toggles and fee configuration are updated
    /// @param depositCancellationsEnabled Whether user-initiated deposit request cancellations are enabled
    /// @param redeemCancellationsEnabled Whether user-initiated redeem request cancellations are enabled
    /// @param depositCancellationFeeNumeraire Fixed pre-deadline deposit cancellation fee, in numeraire
    /// @param redeemCancellationFeeNumeraire Fixed pre-deadline redeem cancellation fee, in numeraire
    /// @param redeemCancellationDynamicFeeCapNumeraire Dynamic pre-deadline redeem cancellation fee cap, in numeraire
    /// @param redeemCancellationCapNumeraire Maximum redeem request size users can self-cancel, in numeraire
    event CancellationDetailsUpdated(
        bool depositCancellationsEnabled,
        bool redeemCancellationsEnabled,
        uint80 depositCancellationFeeNumeraire,
        uint80 redeemCancellationFeeNumeraire,
        uint80 redeemCancellationDynamicFeeCapNumeraire,
        uint80 redeemCancellationCapNumeraire
    );

    /// @notice Emitted when the vault's deposit limits are updated
    /// @param depositCap The new maximum total value that can be deposited into the vault
    /// @param depositRefundTimeout The new time window during which deposits can be refunded
    event DepositDetailsUpdated(uint224 depositCap, uint32 depositRefundTimeout);

    /// @notice Emitted when a token's deposit/withdrawal settings are updated
    /// @param token The token whose settings are being updated
    /// @param tokensDetails The new token details
    event TokenDetailsSet(IERC20 indexed token, TokenDetailsV2 tokensDetails);

    /// @notice Emitted when a token is removed from the provisioner
    /// @param token The token that was removed
    event TokenRemoved(IERC20 indexed token);

    /// @notice Emitted when a user creates a deposit request with a receiver
    /// @param user The address requesting the deposit
    /// @param receiver The address receiving units when solved
    /// @param token The token being deposited
    /// @param tokensIn The amount of tokens to deposit
    /// @param minUnitsOut The minimum amount of units expected
    /// @param solverTip The tip offered to the solver in deposit token terms
    /// @param deadline Timestamp until which the request is valid
    /// @param maxPriceAge Maximum age of price data that solver can use
    /// @param isFixedPrice Whether the request is a fixed price request
    /// @param depositRequestHash The hash of the deposit request
    event DepositRequested(
        address indexed user,
        address indexed receiver,
        IERC20 indexed token,
        uint256 tokensIn,
        uint256 minUnitsOut,
        uint256 solverTip,
        uint256 deadline,
        uint256 maxPriceAge,
        bool isFixedPrice,
        bytes32 depositRequestHash
    );

    /// @notice Emitted when a user creates a redeem request with a receiver
    /// @param user The address requesting the redemption
    /// @param receiver The address receiving tokens when solved
    /// @param token The token requested in return for units
    /// @param minTokensOut The minimum amount of tokens the user expects to receive
    /// @param unitsIn The amount of units being redeemed
    /// @param solverTip The tip offered to the solver in redeem token terms
    /// @param deadline The timestamp until which this request is valid
    /// @param maxPriceAge Maximum age of price data that solver can use
    /// @param isFixedPrice Whether the request is a fixed price request
    /// @param redeemRequestHash The hash of the redeem request
    event RedeemRequested(
        address indexed user,
        address indexed receiver,
        IERC20 indexed token,
        uint256 minTokensOut,
        uint256 unitsIn,
        uint256 solverTip,
        uint256 deadline,
        uint256 maxPriceAge,
        bool isFixedPrice,
        bytes32 redeemRequestHash
    );

    /// @notice Emitted when a user performs synchronous exit (`redeem` or `withdraw`)
    /// @param user The address of the redeemer
    /// @param receiver The address of the receiver
    /// @param token The token being redeemed
    /// @param unitsIn The amount of units burned
    /// @param tokensOut The amount of tokens sent to receiver
    event Redeemed(
        address indexed user, address indexed receiver, IERC20 indexed token, uint256 unitsIn, uint256 tokensOut
    );

    /// @notice Emitted when global sync redeem risk parameters are updated
    /// @param maxPriceAge Maximum allowed vault price age (seconds)
    /// @param relativeCapBps Relative cap in bps of epoch-start TVL (numeraire)
    /// @param absoluteCapNumeraire Absolute cap in numeraire per epoch
    /// @param maxDynamicPremiumBps Maximum global dynamic premium in bps
    event SyncRedeemDetailsUpdated(
        uint24 maxPriceAge, uint16 relativeCapBps, uint80 absoluteCapNumeraire, uint16 maxDynamicPremiumBps
    );

    /// @notice Emitted when the solving gate contract is updated
    /// @param solvingGate The new solving gate address (address(0) disables gating)
    event SolvingGateUpdated(address indexed solvingGate);

    /// @notice Emitted when a receiver updates a depositor's approval to deposit on their behalf
    /// @param receiver The address that will receive units
    /// @param depositor The address being approved or revoked
    /// @param approved Whether the depositor is approved
    event DepositReceiverApprovalSet(address indexed receiver, address indexed depositor, bool approved);

    ////////////////////////////////////////////////////////////
    //                         Errors                         //
    ////////////////////////////////////////////////////////////

    error Aera__SyncDepositDisabled();
    error Aera__AsyncDepositDisabled();
    error Aera__AsyncRedeemDisabled();
    error Aera__DepositCapExceeded();
    error Aera__MinUnitsOutNotMet();
    error Aera__UnitsZero();
    error Aera__TokensZero();
    error Aera__MaxTokensInExceeded();
    error Aera__MaxDepositRefundTimeoutExceeded();
    error Aera__DepositHashNotFound();
    error Aera__HashNotFound();
    error Aera__RefundPeriodExpired();
    error Aera__DeadlineInPast();
    error Aera__DeadlineTooFarInFuture();
    error Aera__DeadlineInFutureAndUnauthorized();
    error Aera__HashCollision();
    error Aera__ZeroAddressPriceAndFeeCalculator();
    error Aera__ZeroAddressMultiDepositorVault();
    error Aera__MultiplierOutOfRange();
    error Aera__DepositCapZero();
    error Aera__PriceAndFeeCalculatorVaultPaused();
    error Aera__AutoPriceSolveNotAllowed();
    error Aera__FixedPriceSolverTipNotAllowed();
    error Aera__TokenCantBePriced();
    error Aera__CallerIsVault();
    error Aera__InvalidToken();
    error Aera__ZeroAddressReceiver();
    error Aera__SyncRedeemRelativeCapBpsTooHigh();
    error Aera__SyncRedeemMaxDynamicPremiumBpsTooHigh();
    error Aera__SyncRedeemMaxPriceAgeZero();
    error Aera__SyncRedeemRelativeCapBpsZero();
    error Aera__SyncRedeemAbsoluteCapNumeraireZero();
    error Aera__SyncRedeemNotConfigured();
    error Aera__SyncRedeemDisabled();
    error Aera__MinTokensOutNotMet();
    error Aera__SyncRedeemMaxPriceAgeExceeded();
    error Aera__SyncRedeemEpochCapExceeded();
    error Aera__MaxUnitsInExceeded();
    error Aera__CallerIsNotRequestUser();
    error Aera__DepositRequestCancellationDisabled();
    error Aera__RedeemRequestCancellationDisabled();
    error Aera__CancellationFeeExceedsRequestAmount();
    error Aera__RequestAmountExceedsRefundCap();
    error Aera__RedeemCancellationCapNumeraireZero();
    error Aera__DepositCancellationDetailsNotZero();
    error Aera__RedeemCancellationDetailsNotZero();
    error Aera__PullFundsSubmitDataNotSet();
    error Aera__SolvingPaused();
    error Aera__SolvingGateDisabled();
    error Aera__ReceiverNotApproved();
    error Aera__UnitsLocked();

    ////////////////////////////////////////////////////////////
    //                        Functions                       //
    ////////////////////////////////////////////////////////////

    /// @notice Deposit tokens directly into the vault
    /// @param token The token to deposit
    /// @param tokensIn The amount of tokens to deposit
    /// @param minUnitsOut The minimum amount of units expected
    /// @param receiver The address that receives units
    /// @return unitsOut The amount of shares minted to the receiver
    /// @dev Caller must be the receiver or approved by the receiver via {setDepositReceiverApproval}
    function deposit(IERC20 token, uint256 tokensIn, uint256 minUnitsOut, address receiver)
        external
        returns (uint256 unitsOut);

    /// @notice Mint exact amount of units by depositing required tokens
    /// @param token The token to deposit
    /// @param unitsOut The exact amount of units to mint
    /// @param maxTokensIn Maximum amount of tokens willing to deposit
    /// @param receiver The address that receives units
    /// @return tokensIn The amount of tokens used to mint the requested shares
    /// @dev Caller must be the receiver or approved by the receiver via {setDepositReceiverApproval}
    function mint(IERC20 token, uint256 unitsOut, uint256 maxTokensIn, address receiver)
        external
        returns (uint256 tokensIn);

    /// @notice Refund a deposit within the refund period
    /// @param sender The original depositor
    /// @param receiver The address whose units are reclaimed
    /// @param token The deposited token
    /// @param tokenAmount The amount of tokens deposited
    /// @param unitsAmount The amount of units minted
    /// @param refundableUntil Timestamp until which refund is possible
    function refundDeposit(
        address sender,
        address receiver,
        IERC20 token,
        uint256 tokenAmount,
        uint256 unitsAmount,
        uint256 refundableUntil
    ) external;

    /// @notice Refund an expired deposit or redeem request
    /// @param token The token involved in the request
    /// @param request The request to refund
    function refundRequest(IERC20 token, RequestV2 calldata request) external;

    /// @notice Cancel an async deposit or redeem request
    /// @param token The token involved in the request
    /// @param request The request to cancel
    function cancelRequest(IERC20 token, RequestV2 calldata request) external;

    /// @notice Create a new deposit request to be solved by solvers
    /// @param token The token to deposit
    /// @param tokensIn The amount of tokens to deposit
    /// @param minUnitsOut The minimum amount of units expected
    /// @param solverTip The tip offered to the solver
    /// @param deadline Timestamp until which the request is valid
    /// @param maxPriceAge Maximum age of price data that solver can use
    /// @param isFixedPrice Whether the request is a fixed price request
    /// @return requestHash The hash identifying the created request
    function requestDeposit(
        IERC20 token,
        uint256 tokensIn,
        uint256 minUnitsOut,
        uint256 solverTip,
        uint256 deadline,
        uint256 maxPriceAge,
        bool isFixedPrice
    ) external returns (bytes32 requestHash);

    /// @notice Create a new redeem request to be solved by solvers
    /// @param token The token to receive
    /// @param unitsIn The amount of units to redeem
    /// @param minTokensOut The minimum amount of tokens expected
    /// @param solverTip The tip offered to the solver
    /// @param deadline Timestamp until which the request is valid
    /// @param maxPriceAge Maximum age of price data that solver can use
    /// @param isFixedPrice Whether the request is a fixed price request
    /// @return requestHash The hash identifying the created request
    function requestRedeem(
        IERC20 token,
        uint256 unitsIn,
        uint256 minTokensOut,
        uint256 solverTip,
        uint256 deadline,
        uint256 maxPriceAge,
        bool isFixedPrice
    ) external returns (bytes32 requestHash);

    /// @notice Solve multiple requests using vault's liquidity, with optional pre/post-solve
    ///         guardian submissions for automatic fund movement
    /// @param token The token for which to solve requests
    /// @param requests Array of requests to solve
    /// @param preSolveSubmitData Encoded operations to submit before solving (e.g., pull funds
    ///        from yield source). If non-empty, calls vault.submit and reverts if it fails
    ///        If empty, skipped
    /// @param postSolveSubmitData Encoded operations to submit after solving (e.g., push funds
    ///        to yield source). If non-empty, calls vault.submit via try/catch - failures are
    ///        swallowed. If empty, skipped
    /// @dev MUST revert if preSolveSubmitData is non-empty and vault.submit reverts
    function solveRequestsVault(
        IERC20 token,
        RequestV2[] calldata requests,
        bytes calldata preSolveSubmitData,
        bytes calldata postSolveSubmitData
    ) external;

    /// @notice Solve multiple requests using solver's own liquidity
    /// @dev Does not check the solving gate because direct solves are peer-to-peer and never touch
    ///      the vault's enter/exit flow, so they have no impact on underlying fund accounting
    ///      The PFC vault-pause check still applies as the full-freeze mechanism
    /// @param token The token for which to solve requests
    /// @param requests Array of requests to solve
    function solveRequestsDirect(IERC20 token, RequestV2[] calldata requests) external;

    /// @notice Update token parameters including push/pull funds SSTORE2 pointers
    /// @param token The token to update
    /// @param details The full token details struct. `pushFundsSubmitDataPointer` and
    ///        `pullFundsSubmitDataPointer` must be valid SSTORE2 pointers or `address(0)` to disable
    /// @dev Admin must create SSTORE2 pointers externally before calling this function
    function setTokenDetails(IERC20 token, TokenDetailsV2 calldata details) external;

    /// @notice Removes token from provisioner
    /// @param token The token to be removed
    function removeToken(IERC20 token) external;

    /// @notice Update deposit parameters
    /// @param depositCap_ New maximum total value that can be deposited
    /// @param depositRefundTimeout_ New time window for deposit refunds
    function setDepositDetails(uint224 depositCap_, uint32 depositRefundTimeout_) external;

    /// @notice Sets cancellation toggles and enabled-side fee configuration
    /// @dev If a deposit/redeem cancellation is disabled, params related to it must be 0
    /// @param depositCancellationsEnabled Whether user-initiated deposit requests can be cancelled
    /// @param redeemCancellationsEnabled Whether user-initiated redeem requests can be cancelled
    /// @param depositCancellationFeeNumeraire Fixed deposit cancellation fee, in numeraire
    /// @param redeemCancellationFeeNumeraire Fixed redeem cancellation fee, in numeraire
    /// @param redeemCancellationDynamicFeeCapNumeraire Dynamic redeem cancellation fee cap, in numeraire
    /// @param redeemCancellationCapNumeraire Maximum redeem request size users can self-cancel, in numeraire
    function setCancellationDetails(
        bool depositCancellationsEnabled,
        bool redeemCancellationsEnabled,
        uint80 depositCancellationFeeNumeraire,
        uint80 redeemCancellationFeeNumeraire,
        uint80 redeemCancellationDynamicFeeCapNumeraire,
        uint80 redeemCancellationCapNumeraire
    ) external;

    /// @notice Create a new deposit request to be solved by solvers
    /// @param token The token to deposit
    /// @param tokensIn The amount of tokens to deposit
    /// @param minUnitsOut The minimum amount of units expected
    /// @param solverTip The tip offered to the solver
    /// @param deadline Timestamp until which the request is valid
    /// @param maxPriceAge Maximum age of price data that solver can use
    /// @param isFixedPrice Whether the request is a fixed price request
    /// @param receiver The address that receives units when solved
    /// @return depositRequestHash The hash of the deposit request
    function requestDeposit(
        IERC20 token,
        uint256 tokensIn,
        uint256 minUnitsOut,
        uint256 solverTip,
        uint256 deadline,
        uint256 maxPriceAge,
        bool isFixedPrice,
        address receiver
    ) external returns (bytes32 depositRequestHash);

    /// @notice Create a new redeem request to be solved by solvers
    /// @param token The token to receive
    /// @param unitsIn The amount of units to redeem
    /// @param minTokensOut The minimum amount of tokens expected
    /// @param solverTip The tip offered to the solver
    /// @param deadline Timestamp until which the request is valid
    /// @param maxPriceAge Maximum age of price data that solver can use
    /// @param isFixedPrice Whether the request is a fixed price request
    /// @param receiver The address that receives tokens when solved
    /// @return redeemRequestHash The hash of the redeem request
    function requestRedeem(
        IERC20 token,
        uint256 unitsIn,
        uint256 minTokensOut,
        uint256 solverTip,
        uint256 deadline,
        uint256 maxPriceAge,
        bool isFixedPrice,
        address receiver
    ) external returns (bytes32 redeemRequestHash);

    /// @notice Sets global sync redeem risk parameters
    /// @param maxPriceAge Maximum allowed vault price age (seconds)
    /// @param relativeCapBps Relative cap in bps of epoch-start TVL (numeraire)
    /// @param absoluteCapNumeraire Absolute cap in numeraire per epoch
    /// @param maxDynamicPremiumBps Maximum global dynamic premium in bps
    /// @dev Only callable by authorized addresses. All parameters must be non-zero
    function setSyncRedeemDetails(
        uint24 maxPriceAge,
        uint16 relativeCapBps,
        uint80 absoluteCapNumeraire,
        uint16 maxDynamicPremiumBps
    ) external;

    /// @notice Approve or revoke a depositor's permission to deposit on behalf of the caller
    /// @param depositor The address to approve or revoke
    /// @param approved Whether the depositor is approved to deposit to the caller
    function setDepositReceiverApproval(address depositor, bool approved) external;

    /// @notice Sets the solving gate contract that controls when solving is allowed
    /// @param solvingGate_ The new solving gate address. Use address(0) to disable gating
    ///        (solving always open)
    /// @dev MUST only be callable by authorized addresses
    /// @dev MUST revert if the solving gate feature is not enabled
    function setSolvingGate(address solvingGate_) external;

    /// @notice Synchronously redeem units for tokens using latest active price
    /// @param token Token to receive
    /// @param unitsIn Units to redeem
    /// @param minTokensOut Minimum acceptable token output
    /// @param receiver Address receiving output tokens
    /// @dev Sync redeem must be enabled for token, vault must be active, and price must be fresh
    /// @return tokensOut Actual token amount sent to receiver
    function redeem(IERC20 token, uint256 unitsIn, uint256 minTokensOut, address receiver)
        external
        returns (uint256 tokensOut);

    /// @notice Synchronously withdraw exact tokens using latest active price
    /// @param token Token to receive
    /// @param tokensOut Exact token output requested
    /// @param maxUnitsIn Maximum acceptable units to burn
    /// @param receiver Address receiving output tokens
    /// @dev Sync redeem must be enabled for token, vault must be active, and price must be fresh
    /// @return unitsIn Actual units burned
    function withdraw(IERC20 token, uint256 tokensOut, uint256 maxUnitsIn, address receiver)
        external
        returns (uint256 unitsIn);

    /// @notice Returns the current solving gate address
    /// @return The solving gate contract address, or address(0) if gating is disabled
    function solvingGate() external view returns (address);

    /// @notice Read an amount relevant for current submit operation from transient storage
    /// @return The stored amount
    function getRelevantAmount() external view returns (uint256);

    /// @notice Return maximum amount that can still be deposited
    /// @return Amount of deposit capacity remaining
    function maxDeposit() external view returns (uint256);

    /// @notice Returns cancellation toggles and fee configuration
    /// @return depositCancellationsEnabled Whether user-initiated deposit request cancellations are enabled
    /// @return redeemCancellationsEnabled Whether user-initiated redeem request cancellations are enabled
    /// @return depositCancellationFeeNumeraire Fixed deposit cancellation fee, in numeraire
    /// @return redeemCancellationFeeNumeraire Fixed redeem cancellation fee, in numeraire
    /// @return redeemCancellationDynamicFeeCapNumeraire Dynamic redeem cancellation fee cap, in numeraire
    /// @return redeemCancellationCapNumeraire Maximum redeem request size users can self-cancel, in numeraire
    function getCancellationDetails()
        external
        view
        returns (
            bool depositCancellationsEnabled,
            bool redeemCancellationsEnabled,
            uint80 depositCancellationFeeNumeraire,
            uint80 redeemCancellationFeeNumeraire,
            uint80 redeemCancellationDynamicFeeCapNumeraire,
            uint80 redeemCancellationCapNumeraire
        );

    /// @notice Preview the cancellation fee for a request in numeraire terms
    /// @dev No guard checks (enable flags, cap, deadline) — those revert in cancelRequest
    /// @param request The request to preview the cancellation fee for
    /// @return The cancellation fee in numeraire
    function previewCancellationFeeNumeraire(RequestV2 calldata request) external view returns (uint256);

    /// @notice Check if a user's units are currently locked
    /// @param user The address to check
    /// @return True if user's units are locked, false otherwise
    function areUserUnitsLocked(address user) external view returns (bool);

    /// @notice Returns all sync redeem configuration and epoch state
    /// @return maxPriceAge Maximum allowed vault price age for sync redeems (seconds)
    /// @return relativeCapBps Relative cap in bps of epoch-start TVL for sync redeems
    /// @return maxDynamicPremiumBps Maximum global dynamic premium in bps for sync redeems
    /// @return epochTimestamp Timestamp of the current sync redeem epoch (from PFC vault state)
    /// @return absoluteCapNumeraire Absolute cap in numeraire per epoch for sync redeems
    /// @return epochRedeemedNumeraire Numeraire amount redeemed globally so far in the current sync redeem epoch
    function getSyncRedeemDetails()
        external
        view
        returns (
            uint24 maxPriceAge,
            uint16 relativeCapBps,
            uint16 maxDynamicPremiumBps,
            uint32 epochTimestamp,
            uint80 absoluteCapNumeraire,
            uint80 epochRedeemedNumeraire
        );

    /// @notice Returns current global sync redeem epoch state
    /// @return epochTimestamp Current anchor epoch timestamp from PFC
    /// @return epochStartTvlNumeraire Epoch-start TVL in numeraire
    /// @return epochRedeemedNumeraire Numeraire amount redeemed globally so far in current epoch
    /// @return epochCapNumeraire Effective current epoch cap in numeraire
    /// @dev MUST NOT revert; returns view-consistent epoch state
    ///      (if PFC is paused, returns zero TVL and zero cap for the current epoch)
    ///      (if PFC timestamp differs from stored, shows fresh epoch with 0 redeemed)
    function getSyncRedeemEpochState()
        external
        view
        returns (
            uint256 epochTimestamp,
            uint256 epochStartTvlNumeraire,
            uint256 epochRedeemedNumeraire,
            uint256 epochCapNumeraire
        );

    /// @notice Computes the hash for a sync deposit
    /// @param user The address making the deposit
    /// @param receiver The address receiving units from the deposit
    /// @param token The token being deposited
    /// @param tokenAmount The amount of tokens to deposit
    /// @param unitsAmount Minimum amount of units to receive
    /// @param refundableUntil The timestamp until which the deposit is refundable
    /// @return The hash of the deposit
    function getDepositHash(
        address user,
        address receiver,
        IERC20 token,
        uint256 tokenAmount,
        uint256 unitsAmount,
        uint256 refundableUntil
    ) external pure returns (bytes32);

    /// @notice Computes the hash for a request
    /// @param token The token in the request
    /// @param request The request to hash
    /// @return The hash of the request
    function getRequestHash(IERC20 token, RequestV2 calldata request) external pure returns (bytes32);
}

